"""Run the Node.js guided workflow generated by ``improve init --language node``.

The check installs a TypeScript SDK package (a packed ``.tgz`` or the built
``sdk/typescript`` directory) into a fresh generated project, then captures a
baseline, freezes a session, applies the documented change, and requires the
comparison to pass. It also checks that a failing agent is retained as a failed
attempt and that ``--check`` reports a missing export.
"""

from __future__ import annotations

import argparse
import json
import shutil
import subprocess  # nosec B404 - fixed Node, npm and Python argv, no shell
import sys
from pathlib import Path
from tempfile import TemporaryDirectory

ROOT = Path(__file__).resolve().parents[1]
CLI = [sys.executable, "-c", "from agentloop.entrypoint import app; app()"]
CHANGE = (
    """  const notes = [];
  for (let index = 0; index < 3; index++) notes.push(await lookupNote(trace, key));
  return { notes };""",
    """  const value = await lookupNote(trace, key);
  return { notes: [value, value, value] };""",
)


def run(argv, cwd, *, expect=0, stdin=None):
    executable = shutil.which(argv[0]) or argv[0]
    completed = subprocess.run(  # nosec B603 - fixed tools and generated local files
        [executable, *argv[1:]],
        cwd=cwd,
        input=stdin,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=600,
        check=False,
    )
    if completed.returncode != expect:
        raise SystemExit(
            f"{' '.join(argv)} exited {completed.returncode}, expected {expect}\n"
            f"{completed.stdout}\n{completed.stderr}"
        )
    return completed


def smoke(sdk: Path, work: Path) -> None:
    project = work / "node-demo"
    run([*CLI, "improve", "init", "--language", "node", "--out", str(project)], work)
    run(["npm", "install", "--no-audit", "--no-fund", str(sdk)], project)
    run(["node", "agentloop_runner.mjs", "--check"], project)
    run(
        [*CLI, "improve", "capture", "--out", "baseline", "--", "node", "agentloop_runner.mjs"],
        project,
    )
    run(
        [*CLI, "improve", "start", "--baseline", "baseline/capture.json", "--out", "optimization"],
        project,
    )
    session = json.loads((project / "optimization/session.json").read_text(encoding="utf-8"))
    cases = session["specification"]["cases"]
    if not all(case["capture_status"] == "completed" for case in cases):
        raise SystemExit("Every Node baseline attempt must complete")
    example = project / "agentloop_example.mjs"
    source = example.read_text(encoding="utf-8")
    if source.count(CHANGE[0]) != 1:
        raise SystemExit("The generated example no longer contains the documented change")
    example.write_text(source.replace(*CHANGE), encoding="utf-8")
    run(
        [*CLI, "improve", "capture", "--out", "candidate", "--", "node", "agentloop_runner.mjs"],
        project,
    )
    run(
        [
            *CLI,
            "improve",
            "finish",
            "--session",
            "optimization/session.json",
            "--candidate",
            "candidate/capture.json",
            "--change",
            "Reuse the lookup result",
            "--out",
            "results",
        ],
        project,
    )
    report = json.loads((project / "results/report.json").read_text(encoding="utf-8"))
    if report["passed"] is not True:
        raise SystemExit("The documented Node change must pass the frozen checks")

    # A connected agent that throws is retained as a failed attempt.
    failing = work / "node-failing"
    failing.mkdir()
    (failing / "agent.mjs").write_text(
        'export async function answer() { throw new Error("synthetic failure"); }\n',
        encoding="utf-8",
    )
    run(
        [
            *CLI,
            "improve",
            "init",
            "--language",
            "node",
            "--agent",
            "agent.mjs:answer",
            "--out",
            ".",
        ],
        failing,
    )
    run(["npm", "install", "--no-audit", "--no-fund", str(sdk)], failing)
    run(
        [*CLI, "improve", "capture", "--out", "baseline", "--", "node", "agentloop_runner.mjs"],
        failing,
        expect=1,
    )
    manifest = json.loads((failing / "baseline/capture.json").read_text(encoding="utf-8"))
    if {row["status"] for row in manifest["runs"]} != {"failed"}:
        raise SystemExit("A throwing Node agent must be recorded as failed attempts")

    # A missing export is reported by --check before any task runs.
    broken = work / "node-missing-export"
    broken.mkdir()
    (broken / "agent.mjs").write_text("export const other = 1;\n", encoding="utf-8")
    run(
        [
            *CLI,
            "improve",
            "init",
            "--language",
            "node",
            "--agent",
            "./agent.mjs:answer",
            "--out",
            ".",
        ],
        broken,
    )
    run(["npm", "install", "--no-audit", "--no-fund", str(sdk)], broken)
    result = run(["node", "agentloop_runner.mjs", "--check"], broken, expect=2)
    if "Cannot connect ./agent.mjs:answer" not in result.stderr:
        raise SystemExit("A missing export must be reported by --check")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "--sdk",
        type=Path,
        default=ROOT / "sdk/typescript",
        help="Packed SDK .tgz or the built sdk/typescript directory.",
    )
    args = parser.parse_args()
    sdk = args.sdk.resolve()
    if not sdk.exists():
        raise SystemExit(f"SDK package not found: {sdk}")
    with TemporaryDirectory(prefix="agentloop-node-guided-") as temporary:
        smoke(sdk, Path(temporary))
    print("Node guided workflow smoke passed")


if __name__ == "__main__":
    main()
